#include <iostream>

// Simulate the mechanics of include guard directives
#ifndef SIMULATED_MATH_LIB_H
#define SIMULATED_MATH_LIB_H

// Inline keyword is required in modern C++ when defined in headers
inline int find_max(int a, int b) {
    return (a > b) ? a : b;
}

inline int find_max(int a, int b, int c) {
    return find_max(find_max(a, b), c);
}

#endif // SIMULATED_MATH_LIB_H

// Second simulated include of the same header block
#ifndef SIMULATED_MATH_LIB_H
#define SIMULATED_MATH_LIB_H
inline int find_max(int a, int b) { return 0; }
#endif

int main() {
    int a = 12;
    int b = 45;
    int c = 27;

    std::cout << find_max(a, b) << " "
              << find_max(b, c) << " "
              << find_max(a, c) << " "
              << find_max(a, b, c) << std::endl;
    return 0;
}

#include <iostream>

int main() {
    // Aliasing demonstration
    int val = 10;
    int *p = &val;
    int *q = &val;
    int *r = &val;
    int *s = &val;

    *q = *p + 1; // val = 11
    *r = *q + 1; // val = 12
    *s = *r + 1; // val = 13
    std::cout << "val=" << val << " *p=" << *p << std::endl;

    // C-string dynamic copy with proper null-termination
    const char src[] = "Tin hoc";
    char *dest = new char[16];
    int idx = 0;
    while (src[idx] != '\0') {
        dest[idx] = src[idx];
        idx++;
    }
    dest[idx] = '\0'; // Crucial null termination

    std::cout << "dest=" << dest << std::endl;
    delete[] dest;

    return 0;
}
